import{_ as a,o as e,c as s,a2 as t}from"./chunks/framework.D66Xq0Kv.js";const h=JSON.parse('{"title":"03 · 基线工作流 W1 — NoobAI 贴线双通道","description":"","frontmatter":{},"headers":[],"relativePath":"03-基线工作流-W1-NoobAI.md","filePath":"03-基线工作流-W1-NoobAI.md"}'),l={name:"03-基线工作流-W1-NoobAI.md"};function r(i,n,o,p,d,c){return e(),s("div",null,[...n[0]||(n[0]=[t(`<h1 id="_03-·-基线工作流-w1-—-noobai-贴线双通道" tabindex="-1">03 · 基线工作流 W1 — NoobAI 贴线双通道</h1><h2 id="_1-工作流-a-—-结构修正版-贴着我的线-修我的错" tabindex="-1">1. 工作流 A — 结构修正版（贴着我的线，修我的错）</h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Load Image]  ←你的画</span></span>
<span class="line"><span>   ├──→ [WD14 Tagger] ──→ 标签 ──→ [CLIP Text Encode]（正向：官方前缀 + 内容标签）</span></span>
<span class="line"><span>   │                                   [CLIP Text Encode]（负向：官方模板）</span></span>
<span class="line"><span>   ├──→ [预处理器 LineartAnime] ──→ [Advanced ControlNet]（Chenkin，Lineart 模式，strength=0.8）</span></span>
<span class="line"><span>   └──→ [VAE Encode] ──→ [Latent]（img2img 起点，denoise=0.45）</span></span>
<span class="line"><span>                                          │</span></span>
<span class="line"><span>                        [KSampler] ←──────┘</span></span>
<span class="line"><span>                        （Euler a / steps 28 / CFG 5 / 官方分辨率档位 / 固定种子）</span></span>
<span class="line"><span>                                          │</span></span>
<span class="line"><span>                              [VAE Decode] → [Save Image]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><p>语义：你的画同时走两条路——线稿被 ControlNet 抓走当骨架约束（贴线），原图被压进潜空间当起点（半改）。&quot;修正解剖但保持构图&quot; = 模型先验 + 两个旋钮，不是提示词在发指令。</p><h2 id="_2-工作流-b-—-理想完成版-平均画师水位线" tabindex="-1">2. 工作流 B — 理想完成版（平均画师水位线）</h2><p>与 A 完全相同，只改两个旋钮：</p><ul><li>ControlNet strength：0.8 → <strong>0.3</strong></li><li>denoise：0.45 → <strong>0.65</strong></li></ul><p>⚠️ 不要加&quot;保持我的风格&quot;——加了就永远看不到成熟标准。</p><h2 id="_3-noobai-xl-v1-1-官方参数-两个官方来源实测对齐" tabindex="-1">3. NoobAI-XL v1.1 官方参数（两个官方来源实测对齐）</h2><p>来源 A：Civitai 官方指南（文章 8962）；来源 B：HF 模型卡 README（<code>Laxhar/noobai-XL-1.1</code>）。</p><table tabindex="0"><thead><tr><th>项</th><th>官方值</th><th>采用</th></tr></thead><tbody><tr><td>采样器</td><td>A：Euler / Euler a；B：Euler a</td><td><strong>Euler a</strong>（v-pred 模型，换采样器可能过饱和/鬼影/黑图）</td></tr><tr><td>步数</td><td>A：28；B：25~30</td><td><strong>28</strong></td></tr><tr><td>CFG</td><td>A：3–5.5；B：5~6</td><td><strong>5</strong></td></tr><tr><td>clip skip</td><td>A：无需设置</td><td>不设置</td></tr><tr><td>VAE</td><td>SDXL 自带，勿换</td><td>不另下</td></tr><tr><td>分辨率</td><td>768×1344 / 832×1216 / 896×1152 / 1024×1024 / 1024×1536 / 1152×896 / 1216×832 / 1344×768 / 1536×1024（B 列表少了 1024×1536/1536×1024）</td><td>按原画比例就近选，动漫竖版 832×1216 或 896×1152；&lt;512 会出错</td></tr></tbody></table><h2 id="_4-提示词模板-官方-可直接照抄" tabindex="-1">4. 提示词模板（官方，可直接照抄）</h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>正向前缀：masterpiece, best quality, newest, absurdres, highres, safe, &lt;WD14 内容标签&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>负向（HF 模型卡原文）：nsfw, worst quality, old, early, low quality, lowres, signature,</span></span>
<span class="line"><span>username, logo, bad hands, mutated hands, mammal, anthro, furry, ambiguous form, feral, semi-anthro</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>提示词书写顺序（官方）：角色数（1girl/1boy）→ 角色名 → 画师 → 场景/镜头 → 动作 → 表情 → 物品 → 质量词。</p><h2 id="_5-chenkin-unicontrol-xl-用法-必须注意" tabindex="-1">5. Chenkin-UniControl-XL 用法（必须注意）</h2><ul><li><strong>不能用 ComfyUI 原生 ControlNet 节点</strong>（官方 README 明确），必须用 <code>ComfyUI-Advanced-ControlNet</code> 插件的 <code>Load Advanced ControlNet Model</code> + <code>Apply Advanced ControlNet</code> 节点</li><li>8 合 1 模式在节点下拉切换：Lineart / Canny / Depth / OpenPose / Tile / Inpaint 等——本工作流用 <strong>Lineart</strong> 模式</li><li>Fuse 模式可多条件合一（线稿+深度+姿势一次调用），示例见 <code>controlnet-fuse.json</code></li><li>许可：fair-ai-public-license-1.0-sd，禁止商用</li></ul><h2 id="_6-现成模板-先下载改-别从零搭" tabindex="-1">6. 现成模板（先下载改，别从零搭）</h2><ul><li>线稿自动上色模板：<a href="https://aigcexe.com/aigc/ai-template/workflow-line-art-coloring-2.html" target="_blank" rel="noreferrer">https://aigcexe.com/aigc/ai-template/workflow-line-art-coloring-2.html</a></li><li>黑白漫画上色模板：<a href="https://aigcexe.com/aigc/ai-template/workflow-manga2anime.html" target="_blank" rel="noreferrer">https://aigcexe.com/aigc/ai-template/workflow-manga2anime.html</a></li><li>风格迁移/参考控制手册：<a href="https://blog.comfy.org/p/the-complete-style-transfer-handbook" target="_blank" rel="noreferrer">https://blog.comfy.org/p/the-complete-style-transfer-handbook</a></li></ul>`,18)])])}const m=a(l,[["render",r]]);export{h as __pageData,m as default};
